function depthOf(root, value) {
  // descend, counting edges as you go
  // running off the tree means the value is absent
}

exam.solution:
function depthOf(root, value) {
  let cur = root;
  let d = 0;
  while (cur !== null) {
    if (value === cur.value) return d;
    cur = value < cur.value ? cur.left : cur.right;
    d += 1;
  }
  return -1;
}

