exam.solution:
function valuesInRange(root, low, high) {
  const out = [];
  function walk(n) {
    if (n === null) return;
    if (low < n.value) walk(n.left);
    if (low <= n.value && n.value <= high) out.push(n.value);
    if (n.value < high) walk(n.right);
  }
  walk(root);
  return out;
}

